def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('payments')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['payment_channel_unread'])
    pt = target_payment(kernel)
    st = target_service(kernel)
    pc = 0
    sc = 0
    for index, record in enumerate(records):
        if not support(witnesses, record, public, True):
            complete = False
            continue
        form = record.get('source_form')
        year = record.get('stated_year')
        payer = record.get('payer')
        payees = record.get('payees')
        amount = record.get('amount')
        payment_date = record.get('payment_date')
        if form not in ('transaction', 'annual_aggregate') or (payer is not None and type(payer) is not str) or type(payees) is not list or len(payees) == 0 or not all(type(x) is str for x in payees) or (amount is not None and type(amount) not in (int, float)):
            complete = False
            continue
        if form == 'annual_aggregate' and (type(year) is not int or payment_date is not None):
            complete = False
            add(reasons, 'annual_payment_has_no_instantaneous_payment_date')
            continue
        if form == 'transaction' and payment_date is not None and type(payment_date) is not str:
            complete = False
            continue
        payment = 'source_payment_' + str(index)
        if record.get('is_query_payment') is True:
            pc += 1
            if type(pt) is str:
                payment = pt
        put(facts, 'payment_', [payment])
        if type(payer) is str:
            put(facts, 'agent_', [payment, payer])
        for payee in payees:
            put(facts, 'patient_', [payment, payee])
        if type(amount) in (int, float):
            put(facts, 'amount_', [payment, amount])
        if type(record.get('payment_medium')) is str:
            put(facts, 'means_', [payment, record.get('payment_medium')])
        if type(payment_date) is str:
            put(facts, 'start_', [payment, payment_date])
        linked = record.get('linked_service')
        if type(linked) is dict:
            service = 'source_payment_service_' + str(index)
            if linked.get('is_query_service') is True:
                sc += 1
                if type(st) is str:
                    service = st
            put(facts, 'service_', [service])
            if type(linked.get('worker')) is str:
                put(facts, 'agent_', [service, linked.get('worker')])
            if type(linked.get('employer')) is str:
                put(facts, 'patient_', [service, linked.get('employer')])
            if type(linked.get('service_kind')) is str:
                put(facts, 'purpose_', [service, linked.get('service_kind')])
            if type(linked.get('service_venue')) is str:
                put(facts, 'location_', [service, linked.get('service_venue')])
            if type(linked.get('service_location')) is str:
                put(facts, 'location_', [service, linked.get('service_location')])
                if type(linked.get('service_country')) is str:
                    put(facts, 'country_', [linked.get('service_location'), linked.get('service_country')])
            if type(linked.get('service_start')) is str:
                put(facts, 'start_', [service, linked.get('service_start')])
            if type(linked.get('service_end')) is str:
                put(facts, 'end_', [service, linked.get('service_end')])
            put(facts, 'purpose_', [payment, service])
        elif type(record.get('purpose_entity')) is str:
            put(facts, 'purpose_', [payment, record.get('purpose_entity')])
    if type(pt) is str and len(records) > 0 and pc != 1:
        complete = False
        add(reasons, 'queried_payment_role_not_uniquely_aligned')
    if sc > 1:
        complete = False
        add(reasons, 'queried_service_role_not_uniquely_aligned')
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
    component = inputs['component_id']
    view = inputs['view']
    public = inputs['public_case']
    kernel = inputs['kernel']
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, True):
        complete = False
        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('givens')
    boundaries = view.get('boundaries')
    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['explicit_legal_channel_unread'])
    expected = {'s151_b':'151(b)','s151_b_applies':'151(b)','s151_c_applies':'151(c)','s152_c_1':'152(c)(1)','s63_f_1_A':'63(f)(1)(A)','s63_f_1_B':'63(f)(1)(B)'}
    seen = set()
    for record in records:
        if not support(witnesses, record, public, True):
            complete = False
            continue
        name = record.get('predicate')
        args = record.get('arguments')
        polarity = record.get('polarity')
        citation = record.get('citation')
        if not valid_given(name, args) or polarity not in ('positive', 'negative') or expected.get(name) != citation:
            complete = False
            continue
        cited = False
        for witness in record.get('witnesses'):
            quote = witness.get('quote')
            if type(quote) is str and citation.lower() in quote.lower().replace('section ', ''):
                cited = True
        if not cited:
            complete = False
            add(reasons, 'exact_statutory_basis_not_source_stated')
            continue
        if is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        key = (name, tuple(args), polarity)
        if key in seen:
            continue
        seen.add(key)
        row = {'predicate': name, 'arguments': list(args)}
        add(negatives if polarity == 'negative' else facts, row)
    for record in boundaries:
        if not support(witnesses, record, public, True) or record.get('kind') not in ('section151_general','section151_d','section63_f_general'):
            complete = False
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

